import React, { useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import {
  Cpu,
  LayoutDashboard,
  Factory,
  Server,
  Radio,
  Sparkles,
  Wrench,
  BarChart3,
  AlertTriangle,
  FileText,
  Settings,
  ChevronDown,
  ChevronRight,
  ChevronLeft,
  Search,
  Activity,
  PlusCircle,
} from 'lucide-react';

const Sidebar = () => {
  const location = useLocation();
  const [collapsed, setCollapsed] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Expand state for each accordion category
  const [openCategories, setOpenCategories] = useState({
    factory: true,
    digitalTwin: false,
    assets: true,
    sensors: false,
    aiIntelligence: true,
    maintenance: false,
    analytics: false,
    alerts: false,
    reports: false,
    settings: false,
  });

  const toggleCategory = (catKey) => {
    setOpenCategories((prev) => ({
      ...prev,
      [catKey]: !prev[catKey],
    }));
  };

  const navCategories = [
    {
      key: 'dashboard',
      title: 'Dashboard',
      icon: LayoutDashboard,
      path: '/',
      subItems: [],
    },
    {
      key: 'factory',
      title: 'Factory',
      icon: Factory,
      badge: '6 Plants',
      subItems: [
        { name: 'Factory Overview', path: '/plants' },
        { name: 'Plants & Production Lines', path: '/plants' },
        { name: 'Factory Map', path: '/plants' },
        { name: 'Production Status', path: '/plants' },
      ],
    },
    {
      key: 'digitalTwin',
      title: 'Digital Twin',
      icon: Cpu,
      badge: 'Live',
      subItems: [
        { name: 'Live Twin', path: '/assets' },
        { name: 'Machine Explorer', path: '/assets' },
        { name: 'Twin Timeline', path: '/assets' },
        { name: 'Machine Comparison', path: '/assets' },
        { name: 'Virtual Factory', path: '/plants' },
      ],
    },
    {
      key: 'assets',
      title: 'Assets',
      icon: Server,
      badge: '20 Looms',
      subItems: [
        { name: 'Asset Inventory', path: '/assets' },
        { name: 'Register Asset', path: '/assets/new' },
        { name: 'Asset Categories', path: '/assets' },
        { name: 'Departments', path: '/assets' },
        { name: 'Asset Lifecycle', path: '/assets' },
      ],
    },
    {
      key: 'sensors',
      title: 'Sensors',
      icon: Radio,
      badge: '136 Feeds',
      subItems: [
        { name: 'Live Monitoring', path: '/assets' },
        { name: 'Temperature', path: '/assets' },
        { name: 'Vibration', path: '/assets' },
        { name: 'RPM', path: '/assets' },
        { name: 'Air Pressure', path: '/assets' },
        { name: 'Yarn Tension', path: '/assets' },
        { name: 'Historical Trends', path: '/assets' },
      ],
    },
    {
      key: 'aiIntelligence',
      title: 'AI Intelligence',
      icon: Sparkles,
      badge: 'RUL 99.4%',
      subItems: [
        { name: 'Health Score', path: '/what-if' },
        { name: 'Failure Prediction', path: '/what-if' },
        { name: 'Remaining Useful Life', path: '/what-if' },
        { name: 'Root Cause Analysis', path: '/what-if' },
        { name: 'What-If AI Simulator', path: '/what-if' },
        { name: 'Smart Recommendations', path: '/what-if' },
      ],
    },
    {
      key: 'maintenance',
      title: 'Maintenance',
      icon: Wrench,
      badge: '3 Scheduled',
      subItems: [
        { name: 'Work Orders', path: '/assets' },
        { name: 'Maintenance Schedule', path: '/assets' },
        { name: 'Maintenance History', path: '/assets' },
        { name: 'Engineers', path: '/assets' },
        { name: 'Spare Parts', path: '/assets' },
      ],
    },
    {
      key: 'analytics',
      title: 'Analytics',
      icon: BarChart3,
      badge: '96.4% OEE',
      subItems: [
        { name: 'Production Analytics', path: '/' },
        { name: 'Machine Performance', path: '/' },
        { name: 'Asset Utilization', path: '/' },
        { name: 'Downtime Analysis', path: '/' },
        { name: 'Energy Consumption', path: '/' },
        { name: 'OEE Dashboard', path: '/' },
      ],
    },
    {
      key: 'alerts',
      title: 'Alerts',
      icon: AlertTriangle,
      badge: '3 Active',
      subItems: [
        { name: 'Active Alerts', path: '/' },
        { name: 'Alert History', path: '/' },
        { name: 'Notifications', path: '/' },
        { name: 'Alarm Rules', path: '/' },
      ],
    },
    {
      key: 'reports',
      title: 'Reports',
      icon: FileText,
      subItems: [
        { name: 'Daily Reports', path: '/' },
        { name: 'Weekly Reports', path: '/' },
        { name: 'Monthly Reports', path: '/' },
        { name: 'AI Reports', path: '/' },
        { name: 'Export', path: '/' },
      ],
    },
    {
      key: 'settings',
      title: 'Settings',
      icon: Settings,
      subItems: [
        { name: 'Users', path: '/' },
        { name: 'Roles', path: '/' },
        { name: 'API Settings', path: '/' },
        { name: 'MQTT Settings', path: '/' },
        { name: 'Preferences', path: '/' },
      ],
    },
  ];

  // Filter categories by search term if typed
  const filteredCategories = navCategories.filter((cat) => {
    if (!searchTerm) return true;
    const matchCat = cat.title.toLowerCase().includes(searchTerm.toLowerCase());
    const matchSub = cat.subItems.some((sub) => sub.name.toLowerCase().includes(searchTerm.toLowerCase()));
    return matchCat || matchSub;
  });

  return (
    <aside className={`sidebar ${collapsed ? 'collapsed' : ''}`}>
      {/* Sidebar Header Brand Logo */}
      <div className="sidebar-brand">
        <div className="brand-icon-box">
          <Cpu size={22} />
        </div>
        {!collapsed && (
          <div className="brand-text-group">
            <span className="brand-title">TexTwin</span>
            <span className="brand-badge">Digital Twin OS</span>
          </div>
        )}
      </div>

      {/* Quick Navigation Filter Input */}
      {!collapsed && (
        <div className="sidebar-search-box">
          <Search size={14} className="sidebar-search-icon" />
          <input
            type="text"
            className="sidebar-search-input"
            placeholder="Search menu..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      )}

      {/* Navigation Tree Menu */}
      <nav className="sidebar-nav">
        {filteredCategories.map((cat) => {
          const Icon = cat.icon;
          const hasSubItems = cat.subItems && cat.subItems.length > 0;
          const isOpen = Boolean(openCategories[cat.key] || searchTerm);
          const isCategoryActive = location.pathname === cat.path;

          // Single Link Item (e.g., Dashboard)
          if (!hasSubItems) {
            return (
              <NavLink
                key={cat.key}
                to={cat.path}
                className={({ isActive }) => `sidebar-link ${isActive ? 'active' : ''}`}
                end
                title={cat.title}
              >
                <Icon size={18} />
                {!collapsed && <span className="sidebar-link-text">{cat.title}</span>}
              </NavLink>
            );
          }

          // Expandable Tree Category Header
          return (
            <div key={cat.key} className="sidebar-category-group">
              <div
                className={`sidebar-category-header ${isCategoryActive ? 'active-cat' : ''}`}
                onClick={() => !collapsed && toggleCategory(cat.key)}
                title={cat.title}
              >
                <div className="category-left">
                  <Icon size={18} className="category-icon" />
                  {!collapsed && <span className="category-title">{cat.title}</span>}
                </div>

                {!collapsed && (
                  <div className="category-right">
                    {cat.badge && <span className="sidebar-mini-badge">{cat.badge}</span>}
                    {isOpen ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                  </div>
                )}
              </div>

              {/* Sub-Items Tree */}
              {!collapsed && isOpen && (
                <div className="sidebar-submenu">
                  {cat.subItems.map((sub, sIdx) => {
                    const isSubMatch = searchTerm && sub.name.toLowerCase().includes(searchTerm.toLowerCase());
                    return (
                      <NavLink
                        key={sIdx}
                        to={sub.path}
                        className={({ isActive }) =>
                          `sidebar-sublink ${isActive || isSubMatch ? 'sub-active' : ''}`
                        }
                        title={sub.name}
                      >
                        <span className="sublink-tree-icon">├─</span>
                        <span className="sublink-text">{sub.name}</span>
                      </NavLink>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </nav>

      {/* Live Operational Status Widget */}
      {!collapsed && (
        <div className="sidebar-status-box">
          <div className="status-box-header">
            <Activity size={15} style={{ color: 'var(--status-running)' }} />
            <span>Digital Twin Sync</span>
          </div>
          <p className="status-box-sub">Connected to 20 Weaving Looms</p>
        </div>
      )}

      {/* Collapse/Expand Sidebar Trigger Button */}
      <button
        className="sidebar-toggle-btn"
        onClick={() => setCollapsed(!collapsed)}
        title={collapsed ? 'Expand Sidebar Menu' : 'Collapse Sidebar Menu'}
      >
        {collapsed ? <ChevronRight size={18} /> : <ChevronLeft size={18} />}
      </button>
    </aside>
  );
};

export default Sidebar;
